import{_ as t,o,c as i,a2 as a}from"./chunks/framework.DBSoX6Zw.js";const u=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),s={name:"guide/security.md"};function n(r,e,l,c,d,p){return o(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Plik allows users to upload and serve any content as-is. Hosting untrusted content raises security concerns that Plik addresses with several mechanisms.</p><h2 id="content-type-override" tabindex="-1">Content-Type Override <a class="header-anchor" href="#content-type-override" aria-label="Permalink to &quot;Content-Type Override&quot;">​</a></h2><p>For security reasons, Plik doesn&#39;t trust user-provided MIME types and relies solely on server-side detection. This means some files may not render properly in browsers or embedded viewers that require the correct MIME type.</p><div class="warning custom-block"><p class="custom-block-title">Office format detection limitation</p><p>Office formats like <code>.pptx</code>, <code>.docx</code>, and <code>.xlsx</code> are ZIP archives internally, so Go&#39;s built-in MIME detector (<code>http.DetectContentType</code>) identifies them as <code>application/zip</code> instead of their proper types (e.g., <code>application/vnd.openxmlformats-officedocument.presentationml.presentation</code>).</p></div><h2 id="enhanced-web-security" tabindex="-1">Enhanced Web Security <a class="header-anchor" href="#enhanced-web-security" aria-label="Permalink to &quot;Enhanced Web Security&quot;">​</a></h2><p>When <code>EnhancedWebSecurity</code> is enabled in <code>plikd.cfg</code>, Plik sets additional HTTP headers:</p><ul><li><strong>X-Content-Type-Options</strong>: <code>nosniff</code></li><li><strong>X-XSS-Protection</strong>: enabled</li><li><strong>X-Frame-Options</strong>: deny</li><li><strong>Content-Security-Policy</strong>: restrictive policy disabling resource loading, XHR, iframes</li><li><strong>Secure Cookies</strong>: session cookies only transmitted over HTTPS</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Enhanced security will break audio/video playback, PDF rendering, and other rich content features. Disable it if you need those capabilities.</p></div><div class="danger custom-block"><p class="custom-block-title">Authentication requires HTTPS with EnhancedWebSecurity</p><p>When <code>EnhancedWebSecurity</code> is enabled, session cookies have the <code>Secure</code> flag set and can only be transmitted over HTTPS connections. Authentication will not work over plain HTTP.</p></div><h2 id="download-domain" tabindex="-1">Download Domain <a class="header-anchor" href="#download-domain" aria-label="Permalink to &quot;Download Domain&quot;">​</a></h2><p>It is recommend to serve uploaded files on a separate (sub-)domain to:</p><ul><li>Protect against phishing links using your main domain</li><li>Protect Plik&#39;s session cookie from being exposed to uploaded content</li></ul><p>Configure with <code>DownloadDomain</code> in <code>plikd.cfg</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DownloadDomain = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://dl.plik.example.com&quot;</span></span></code></pre></div><h3 id="troubleshooting-redirect-loops" tabindex="-1">Troubleshooting: Redirect Loops <a class="header-anchor" href="#troubleshooting-redirect-loops" aria-label="Permalink to &quot;Troubleshooting: Redirect Loops&quot;">​</a></h3><p>If you see this error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invalid download domain 127.0.0.1:8080, expected plik.root.gg</span></span></code></pre></div><p><code>DownloadDomain</code> checks the <code>Host</code> header of incoming HTTP requests. By default, reverse proxies like Nginx and Apache do not forward this header. Make sure to configure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Apache mod_proxy: ProxyPreserveHost On</span></span>
<span class="line"><span>Nginx:            proxy_set_header Host $host;</span></span></code></pre></div><h2 id="xsrf-protection" tabindex="-1">XSRF Protection <a class="header-anchor" href="#xsrf-protection" aria-label="Permalink to &quot;XSRF Protection&quot;">​</a></h2><p>Plik uses a dual-cookie XSRF protection mechanism:</p><ol><li>The <code>plik-xsrf</code> cookie value must be copied into the <code>X-XSRFToken</code> HTTP header for all mutating authenticated requests</li><li>This prevents cross-site request forgery attacks</li></ol><h2 id="upload-restrictions" tabindex="-1">Upload Restrictions <a class="header-anchor" href="#upload-restrictions" aria-label="Permalink to &quot;Upload Restrictions&quot;">​</a></h2><h3 id="source-ip-whitelist" tabindex="-1">Source IP Whitelist <a class="header-anchor" href="#source-ip-whitelist" aria-label="Permalink to &quot;Source IP Whitelist&quot;">​</a></h3><p>Restrict uploads and user creation to specific IP ranges:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UploadWhitelist = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.0/8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.0/24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>Set <code>FeatureAuthentication = &quot;forced&quot;</code> to require authentication for all uploads.</p><h3 id="upload-tokens" tabindex="-1">Upload Tokens <a class="header-anchor" href="#upload-tokens" aria-label="Permalink to &quot;Upload Tokens&quot;">​</a></h3><p>Authenticated users can generate upload tokens to link CLI uploads to their account. Tokens are sent via the <code>X-PlikToken</code> HTTP header.</p><h2 id="link-preview-bot-protection" tabindex="-1">Link Preview Bot Protection <a class="header-anchor" href="#link-preview-bot-protection" aria-label="Permalink to &quot;Link Preview Bot Protection&quot;">​</a></h2><p>Messaging apps like Slack, Telegram, WhatsApp, Signal, Discord, and others generate link previews by fetching shared URLs. This is problematic for:</p><ul><li><strong>One-shot uploads</strong>: the bot&#39;s preview request counts as the single allowed download, deleting the file before the intended recipient can access it</li><li><strong>Streaming uploads</strong>: the bot consumes the stream data, leaving nothing for the real downloader</li></ul><p>Plik automatically blocks known messaging app link preview bots from downloading one-shot and streaming files, returning a <strong>406 Not Acceptable</strong> response. Normal (multi-download) uploads are not affected — bots can still generate previews for those.</p><div class="tip custom-block"><p class="custom-block-title">No configuration needed</p><p>This protection is always active and requires no configuration. It uses a hardcoded list of known bot user-agent strings that is maintained with Plik releases.</p></div><h3 id="blocked-bots" tabindex="-1">Blocked Bots <a class="header-anchor" href="#blocked-bots" aria-label="Permalink to &quot;Blocked Bots&quot;">​</a></h3><p>Slack, Telegram, WhatsApp, Signal, Facebook/Messenger, Discord, Skype, Viber, LinkedIn, Twitter/X, Microsoft Teams, Wire, Mattermost, Rocket.Chat, and Zulip.</p>`,38)])])}const k=t(s,[["render",n]]);export{u as __pageData,k as default};
